import json
import datetime
try:
    prods = vars.get('products')
    if isinstance(prods, str):
        try:
            prods = json.loads(prods)
        except Exception:
            prods = None
    p = None
    if isinstance(prods, list) and prods:
        p = prods[0]
    if not isinstance(p, dict):
        p = {}
        def g(k):
            return vars.get('get_account_response.data.products.0.' + k) or vars.get('fetch_account_response.data.products.0.' + k)
        for k in ['product_id', 'type', 'card_last4', 'past_due', 'days_late', 'minimum_payment', 'instalment_amount']:
            v = g(k)
            if v is not None:
                p[k] = v
    typ = str(p.get('type') or '')
    vars['product_id'] = str(p.get('product_id') or 'p1')
    if typ == 'credit_card':
        vars['product_say'] = str(p.get('card_last4') or '') + ' ile biten kredi kartınız'
        floor = p.get('minimum_payment')
    elif typ == 'car_loan':
        vars['product_say'] = 'taşıt krediniz'
        floor = p.get('instalment_amount')
    else:
        vars['product_say'] = 'ihtiyaç krediniz'
        floor = p.get('instalment_amount')
    def num(x):
        try:
            return float(x)
        except Exception:
            return 0.0
    pd = num(p.get('past_due'))
    fl = num(floor)
    dl = int(num(p.get('days_late')))
    def fmt(x):
        s = ('%.2f' % x)
        if s.endswith('.00'):
            s = s[:-3]
        return s
    vars['past_due'] = fmt(pd)
    vars['floor_amt'] = fmt(fl)
    vars['days_late'] = str(dl)
    if dl <= 7:
        vars['band'] = 'erken'
        vars['deadline_iso'] = str(vars.get('deadline_early'))
        vars['attempts_allowed'] = '1'
        vars['attempt_text'] = 'Bu müşteri ERKEN bantta: yalnızca 1 ikna denemesi var (bu haftanın son iş günü önerisi). 2. deneme YOK.'
    else:
        vars['band'] = 'geç'
        vars['deadline_iso'] = str(vars.get('deadline_late'))
        vars['attempts_allowed'] = '2'
        vars['attempt_text'] = 'Bu müşteri GEÇ bantta: 2 ikna denemesi var. 1. deneme: bu haftanın son iş günü. 2. deneme: alt sınır tutarı (' + fmt(fl) + ' TL) son tarihte (' + str(vars.get('deadline_late')) + ').'
    AY = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
    GUN = ['Pazartesi', 'Salı', 'Çarşamba', 'Perşembe', 'Cuma', 'Cumartesi', 'Pazar']
    d = datetime.date.fromisoformat(vars['deadline_iso'][:10])
    vars['deadline_say'] = str(d.day) + ' ' + AY[d.month - 1] + ' ' + GUN[d.weekday()]
    vars['account_state'] = 'ok' if p.get('past_due') is not None else 'missing'
except Exception as e:
    vars['account_state'] = 'error ' + str(e)
    for k in ['product_say', 'past_due', 'floor_amt', 'days_late', 'deadline_iso', 'deadline_say', 'attempt_text', 'band', 'product_id']:
        vars.setdefault(k, '')
